function indexOf(arr, x) {
  let lo = 0, hi = arr.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) / 2;
    if (arr[mid] === x) return mid;
    if (arr[mid] < x) lo = mid + 1; else hi = mid - 1;
  }
  return -1;
}
module.exports = { indexOf };

It claims to be binary search over a sorted number array but users report it returns -1 for values that are present. Using node:test (node --test), first write bsearch.test.js with a failing case such as indexOf([1,2,3,4,5,6,7], 6), run it, and show the failure. Diagnose why (mid becomes fractional, arr[mid] is undefined), fix with integer midpoint math, then add a randomized cross-check test against Array.prototype.indexOf on 500 generated sorted arrays. All tests must pass with node --test.

