result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/bsearch.test.js", "content": "'use strict';

const test = require('node:test');
const assert = require('node:assert');
const { indexOf } = require('./bsearch.js');

test('finds an existing value in a sorted array', () => {
  assert.strictEqual(indexOf([1, 2, 3, 4, 5, 6, 7], 6), 5);
});

test('returns -1 for missing values', () => {
  assert.strictEqual(indexOf([1, 2, 3, 4, 5, 6, 7], 0), -1);
  assert.strictEqual(indexOf([1, 2, 3, 4, 5, 6, 7], 8), -1);
});

test('handles empty array', () => {
  assert.strictEqual(indexOf([], 1), -1);
});

test('randomized cross-check against Array.prototype.indexOf', () => {
  for (let i = 0; i < 500; i++) {
    // Generate a random sorted array (allow duplicates)
    const len = Math.floor(Math.random() * 50); // 0..49
    const arr = [];
    let v = Math.floor(Math.random() * 100) - 50;
    for (let j = 0; j < len; j++) {
      arr.push(v);
      v += Math.floor(Math.random() * 5); // non-decreasing
    }
    // Query with both present and possibly-absent values
    const queries = [
      arr[Math.floor(Math.random() * len)], // may be undefined if empty
      Math.floor(Math.random() * 200) - 100,
    ];
    for (const q of queries) {
      const expected = arr.indexOf(q);
      assert.strictEqual(
        indexOf(arr, q),
        expected,
        `indexOf([${arr}], ${q}) should be ${expected}`
      );
    }
  }
});
"})
