  let lo = 0, hi = arr.length - 1;
  let result = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >>> 1; // integer midpoint: >>>1 floors safely
    if (arr[mid] === x) {
      result = mid;      // record match...
      hi = mid - 1;      // ...but keep searching left for first occurrence
    } else if (arr[mid] < x) {
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return result;
}
module.exports = { indexOf };
